// Logs → Automations tab — every schedule FIRE, AS GRAPH SOURCE (epic #3604).
//
// The history half of the Automations page, moved here when the config half moved onto the persona
// (hooks-and-schedules-belong-to-the-persona). It is the same split the whole refactor keeps making:
// what an agent IS goes beside the agent, what it DID goes to the logs.
//
// THIS IS NOW THE ONLY RECORD OF A FIRE. Runs used to live as a `runs[]` array on the automation
// record, capped at 25, alongside a mutable `nextRunAt`. Both are gone — the scheduler derives
// due-ness from this log, so the history and the bookkeeping cannot disagree about whether something
// ran. That also means a cleared log makes every schedule look never-run, which is why the empty
// state says what it means rather than "no runs yet".
//
// Preview note: the log line shape is inlined so this previews standalone; every prop still overrides
// the sample when composed by LogsWorkspace.
import { StatTile } from "@/shared/ui/data/StatTile";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";

/** One parsed fire: `ts · pane · <persona>:<schedule> · status · note`. */
export interface AutomationRunRow {
  at: number;
  pane: string;
  schedule: string;
  status: string;
  note: string;
}

const NOW = 1700000000000;
const SAMPLE: AutomationRunRow[] = [
  { at: NOW - 60000, pane: "t0p1", schedule: "persona-janitor:nightly-gc", status: "ok", note: "ran in t0p1" },
  { at: NOW - 3600000, pane: "", schedule: "persona-marketer:weekly-digest", status: "skipped", note: "no open pane is running persona-marketer" },
  { at: NOW - 7200000, pane: "t0p1", schedule: "persona-janitor:nightly-gc", status: "fail", note: "pty write failed" },
];

/**
 * Parse the automation log, NEWEST FIRST.
 *
 * Tolerant by design: this is the only record of a fire, so a malformed line is skipped rather than
 * allowed to abort the parse and hide every good line after it.
 */
export function parseAutomationLog(lines: string[]): AutomationRunRow[] {
  const out: AutomationRunRow[] = [];
  for (const line of lines ?? []) {
    const [ts, pane, schedule, status, ...rest] = line.split("\t");
    if (!ts || !schedule) continue;
    const at = Date.parse(ts);
    if (Number.isNaN(at)) continue;
    out.push({ at, pane: pane ?? "", schedule, status: status ?? "", note: rest.join("\t") });
  }
  return out.sort((a, b) => b.at - a.at);
}

/** The carrier persona of a `<persona>:<schedule>` key. */
export function carrierOf(key: string): string {
  const i = key.indexOf(":");
  return i < 0 ? key : key.slice(0, i);
}

/** Fire counts by outcome. `skipped` is NOT a failure — it means the agent was not running. */
export function runTotals(rows: AutomationRunRow[]) {
  return {
    runs: rows.length,
    ok: rows.filter((r) => r.status === "ok").length,
    skipped: rows.filter((r) => r.status === "skipped").length,
    failed: rows.filter((r) => r.status === "fail").length,
    schedules: new Set(rows.map((r) => r.schedule)).size,
  };
}

/** `3m ago` / `2h ago` / `4d ago`; clamps a future stamp rather than rendering a negative age. */
export function fmtAgo(at: number, now: number): string {
  const m = Math.floor(Math.max(0, now - at) / 60000);
  if (m < 1) return "just now";
  if (m < 60) return m + "m ago";
  const h = Math.floor(m / 60);
  if (h < 24) return h + "h ago";
  return Math.floor(h / 24) + "d ago";
}

const STATUS: Record<string, { label: string; color: string }> = {
  ok: { label: "ran", color: "var(--success)" },
  skipped: { label: "skipped", color: "var(--state-wait)" },
  fail: { label: "failed", color: "var(--danger)" },
};

export interface AutomationsTabProps {
  rows?: AutomationRunRow[];
  loaded?: boolean;
  now?: number;
  limit?: number;
}

export function AutomationsTab({ rows = SAMPLE, loaded = true, now = NOW, limit = 80 }: AutomationsTabProps) {
  const t = runTotals(rows);
  const COLS = "96px 1fr 88px 1.4fr";

  return (
    <Box style={{ display: "flex", flexDirection: "column", width: "100%" }}>
      <Box style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 10, marginBottom: 14 }}>
        <StatTile k="fires" v={t.runs} sub={t.schedules + " distinct schedules"} />
        <StatTile k="ran" v={t.ok} tone="success" sub="reached a terminal" />
        <StatTile k="skipped" v={t.skipped} sub="carrier was not running" />
        <StatTile k="failed" v={t.failed} tone={t.failed > 0 ? "danger" : undefined} sub="write did not land" />
      </Box>

      {rows.length === 0 ? (
        <EmptyState
          iconVariant="dashed" icon="◔" size="sm"
          title={loaded ? "No schedule has fired yet" : "Reading the automation log…"}
          description="A schedule is carried by a persona and fires into the pane running it. Every fire is recorded here — this log is the only record of one, and the scheduler reads it back to decide what is due."
        />
      ) : (
        <Box border="soft" radius={7} style={{ overflow: "hidden" }}>
          <Box style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, padding: "7px 12px", background: "var(--bg-elev2)", borderBottom: "1px solid var(--border-soft)", fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".05em" }}>
            <Box as="span">when</Box><Box as="span">schedule</Box><Box as="span">outcome</Box><Box as="span">note</Box>
          </Box>
          {rows.slice(0, limit).map((r, i) => {
            const st = STATUS[r.status] ?? { label: r.status || "unknown", color: "var(--fg-dim)" };
            return (
              <Box key={r.at + ":" + r.schedule + ":" + i} style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, alignItems: "baseline", padding: "8px 12px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)" }}>
                <Text as="span" mono size={10.5} tone="dim">{fmtAgo(r.at, now)}</Text>
                <Box as="span" style={{ minWidth: 0, display: "inline-flex", gap: 6, alignItems: "baseline" }}>
                  <Text as="span" mono size={11} style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r.schedule}</Text>
                </Box>
                <Text as="span" mono size={10.5} style={{ color: st.color }}>{st.label}</Text>
                <Text as="span" tone="muted" size={10.5} style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r.note}</Text>
              </Box>
            );
          })}
        </Box>
      )}
      {rows.length > limit && (
        <Text as="div" mono size={10} tone="dim" style={{ marginTop: 7 }}>showing {limit} of {rows.length}</Text>
      )}
    </Box>
  );
}
